std::string s = "ABCDEFGHI";
auto it = s.begin();

// O(1) Random Access Iterator Arithmetic:
char fifth = *(it + 4);

// O(1) Iterator Difference:
std::ptrdiff_t diff = s.end() - s.begin(); // diff == 9

// Standard library requirement for Random Access:
it += 3; // Jump in constant time
it[2];   // O(1) indexed access via iterator

// For std::string, iterators are usually
// just wrapper around T* (char*)

std::string s2(100, 'Z');
// Iterators == Pointers in practice (Zero-cost abstraction):
char* raw_ptr = &s2[0];
auto it_start = s2.begin();
// &(*it_start) == raw_ptr

// Contrast: std::list iterators are not random access
std::list<char> l = {'X', 'Y', 'Z'};
auto lit = l.begin();
// *(lit + 2) -> ERROR (No O(1) jump)
std::advance(lit, 2); // O(N) traversal required
char third = *lit;
